def icpplane(a,b,T=None,iters=40):
 if T is None:T=np.eye(4)
 tree=cKDTree(b);ix=tree.query(b,k=12)[1];bs=b[ix];bs-=bs.mean(1)[:,None,:];_,v=np.linalg.eigh(np.einsum('nki,nkj->nij',bs,bs));ns=v[:,:,0]
 for _ in range(iters):
  aa=transform(a,T);d,ix=tree.query(aa);m=d<.025;x=aa[m];y=b[ix[m]];n=ns[ix[m]];err=np.einsum('ij,ij->i',x-y,n);m2=np.abs(err)<.008;x=x[m2];y=y[m2];n=n[m2];err=err[m2]
  cen=x.mean(0);J=np.c_[np.cross(x-cen,n),n];delta=np.linalg.lstsq(J,-err,rcond=None)[0];R=Rot.from_rotvec(delta[:3]).as_matrix();t=cen-R@cen+delta[3:];T[:3,3]=R@T[:3,3]+t;T[:3,:3]=R@T[:3,:3]
  if np.linalg.norm(delta)<1e-6:break
 return T,np.sqrt(np.mean(err**2))
