def track_goals(o, previous_goal, seconds=3, prefix='track'):
 """Follow exposed sequential goal poses; stop for visual correction if needed."""
 for _ in range(32):
  idx=o.meta['task']['goal_index'];g=goalT(o)
  o=movetool(o,previous_goal,g,seconds,f'{prefix}_{idx}');previous_goal=g
  if o.meta['done'] or o.meta['task']['goal_index']==idx:break
 return o,previous_goal

def local_pose_search(o, offsets, rotations, seconds=.6, prefix='search'):
 """Test bounded visual-pose uncertainty using only reported goal advancement."""
 G=goalT(o);F=fk(target(o));q=target(o);idx=o.meta['task']['goal_index']
 for k,rv in enumerate(rotations):
  R=G[:3,:3]@Rot.from_rotvec(rv).as_matrix()@G[:3,:3].T
  D=np.eye(4);D[:3,:3]=R;D[:3,3]=G[:3,3]-R@G[:3,3]
  for j,dp in enumerate(offsets):
   des=D@F;des[:3,3]+=dp;q=ik(des,q)
   o=move(q,seconds,f'{prefix}_{k}_{j}')
   if o.meta['done'] or o.meta['task']['goal_index']>idx:return o
 return o
